package com.cloudmusic2ktv.dlna;

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Bounded streaming HTTP endpoint for one remote or local media source. */
final class HttpRelay implements AutoCloseable {
    interface Connections { HttpURLConnection open(URL url) throws IOException; }
    interface Observer { void completed(String method, int status, long bytes); }
    interface Source { Response open(String method, Map<String, String> headers) throws IOException; }
    static final class Response implements Closeable {
        final int status; final Map<String, String> headers; final InputStream body; private final Closeable closer;
        Response(int status, Map<String, String> headers, InputStream body, Closeable closer) { this.status=status; this.headers=headers; this.body=body; this.closer=closer; }
        @Override public void close() throws IOException { if (closer != null) closer.close(); }
    }
    private final Source source; private final Observer observer; private final ServerSocket server; private final String path;
    private final Set<Socket> clients=ConcurrentHashMap.newKeySet(); private final Set<Response> upstreams=ConcurrentHashMap.newKeySet();
    private final ThreadPoolExecutor workers=new ThreadPoolExecutor(4,4,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8),r->new Thread(r,"media-relay-transfer"));
    private volatile boolean closed;
    HttpRelay(InetAddress address,String mediaUrl,Connections connections,Observer observer)throws IOException { DlnaRenderer.validateUrl(mediaUrl); URL initial=new URL(mediaUrl); source=new RemoteSource(initial,connections); this.observer=observer; path=randomPath(extension(initial.getPath())); server=bind(address); start(); }
    HttpRelay(InetAddress address,String extension,Source source,Observer observer)throws IOException { this.source=source; this.observer=observer; path=randomPath(extension==null?".mp4":extension); server=bind(address); start(); }
    private static String extension(String path){String p=path.toLowerCase(Locale.ROOT);return p.endsWith(".mp4")?".mp4":p.endsWith(".avi")?".avi":"";}
    private static String randomPath(String ext){return "/video/"+UUID.randomUUID()+ext;}
    private static ServerSocket bind(InetAddress address)throws IOException{ServerSocket socket=new ServerSocket();try{socket.bind(new InetSocketAddress(address,0));return socket;}catch(IOException e){socket.close();throw e;}}
    private void start(){new Thread(this::accept,"media-relay-listener").start();}
    String url(){return "http://"+server.getInetAddress().getHostAddress()+":"+server.getLocalPort()+path;}
    private void accept(){while(!closed)try{Socket client=server.accept();clients.add(client);if(closed)closeClient(client);else try{workers.execute(()->serve(client));}catch(RejectedExecutionException e){closeClient(client);}}catch(IOException e){if(!closed)close();}}
    private void serve(Socket client){Response response=null;int status=502;long copied=0;String method="UNKNOWN";boolean sent=false;try{client.setSoTimeout(10000);InputStream input=new BufferedInputStream(client.getInputStream());OutputStream output=client.getOutputStream();String[] lines=readHeader(input).split("\r\n");String[] request=lines[0].split(" ");if(request.length!=3){status=400;reply(output,status);return;}method=request[0];if(!path.equals(request[1])){status=404;reply(output,status);return;}if(!method.equals("GET")&&!method.equals("HEAD")){status=405;reply(output,status);return;}Map<String,String> headers=new HashMap<>();for(int i=1;i<lines.length;i++){int colon=lines[i].indexOf(':');if(colon<1){status=400;reply(output,status);return;}String key=lines[i].substring(0,colon).toLowerCase(Locale.ROOT);if(key.equals("range")||key.equals("if-range")){if(headers.put(key,lines[i].substring(colon+1).trim())!=null){status=400;reply(output,status);return;}}}response=source.open(method,headers);upstreams.add(response);status=response.status;StringBuilder wire=new StringBuilder("HTTP/1.1 ").append(status).append(" Relay\r\nConnection: close\r\n");for(Map.Entry<String,String> entry:response.headers.entrySet())if(entry.getKey().indexOf('\r')<0&&entry.getKey().indexOf('\n')<0&&entry.getValue()!=null&&entry.getValue().indexOf('\r')<0&&entry.getValue().indexOf('\n')<0)wire.append(entry.getKey()).append(": ").append(entry.getValue()).append("\r\n");output.write(wire.append("\r\n").toString().getBytes(StandardCharsets.ISO_8859_1));sent=true;if(method.equals("GET")&&response.body!=null)try(InputStream body=response.body){byte[] buffer=new byte[64*1024];int count;while(!closed&&(count=body.read(buffer))!=-1){output.write(buffer,0,count);copied+=count;}}output.flush();}catch(IOException|IllegalArgumentException e){if(!sent)try{reply(client.getOutputStream(),status);}catch(IOException ignored){}}finally{if(response!=null){upstreams.remove(response);try{response.close();}catch(IOException ignored){}}closeClient(client);if(observer!=null)observer.completed(method,status,copied);}}
    private static final class RemoteSource implements Source {private final URL initial;private final Connections connections;RemoteSource(URL initial,Connections connections){this.initial=initial;this.connections=connections;}public Response open(String method,Map<String,String> headers)throws IOException{URL current=initial;for(int redirects=0;redirects<=5;redirects++){DlnaRenderer.validateUrl(current.toExternalForm());HttpURLConnection connection=connections.open(current);try{connection.setConnectTimeout(10000);connection.setReadTimeout(20000);connection.setInstanceFollowRedirects(false);connection.setRequestMethod(method);connection.setRequestProperty("Accept-Encoding","identity");for(Map.Entry<String,String> e:headers.entrySet())connection.setRequestProperty(e.getKey(),e.getValue());int status=connection.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){String next=connection.getHeaderField("Location");if(next==null)throw new IOException("Missing redirect location");current=new URL(current,next);connection.disconnect();continue;}InputStream body=status>=400?connection.getErrorStream():connection.getInputStream();Map<String,String> responseHeaders=new LinkedHashMap<>();for(String key:new String[]{"Content-Type","Content-Length","Content-Range","Accept-Ranges","Content-Encoding","ETag","Last-Modified"}){String value=connection.getHeaderField(key);if(value!=null)responseHeaders.put(key,value);}return new Response(status,responseHeaders,body,connection::disconnect);}catch(IOException|RuntimeException e){connection.disconnect();throw e;}}throw new IOException("Too many redirects");}}
    private static String readHeader(InputStream input)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();int tail=0;while(bytes.size()<16384){int value=input.read();if(value<0)throw new EOFException();bytes.write(value);tail=(tail<<8)|value;if(tail==0x0d0a0d0a)return bytes.toString("ISO-8859-1");}throw new IOException("Request header too large");}
    private static void reply(OutputStream output,int status)throws IOException{output.write(("HTTP/1.1 "+status+" Relay\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));}
    private void closeClient(Socket client){clients.remove(client);try{client.close();}catch(IOException ignored){}}
    @Override public synchronized void close(){if(closed)return;closed=true;try{server.close();}catch(IOException ignored){}for(Socket client:clients)closeClient(client);workers.shutdownNow();new Thread(()->{for(Response response:upstreams)try{response.close();}catch(IOException ignored){ }},"media-relay-close").start();}
}
